        // Catalog descriptions — one per RecommendedModel.Id (HuggingFaceService catalog)
        ["modelsm.desc.qwen3.8-27b"] = new() { ["en"] = "Qwen's newest dense model: strongest all-rounder that still runs on one 24 GB card — coding, agents, long documents, images and video.", ["th"] = "โมเดล dense รุ่นใหม่ล่าสุดของ Qwen เก่งรอบด้านที่สุดที่ยังรันบนการ์ด 24 GB ใบเดียวได้ ทั้งเขียนโค้ด งานเอเจนต์ เอกสารยาว รูปภาพและวิดีโอ" },
        ["modelsm.desc.qwen3.6-35b-a3b"] = new() { ["en"] = "Mixture-of-experts: 35B of knowledge but only 3B active per token, so it stays quick even when part of it sits in system RAM. Tuned for agentic coding.", ["th"] = "แบบ MoE: ความรู้ระดับ 35B แต่ใช้จริงแค่ 3B ต่อโทเคน จึงยังเร็วแม้บางส่วนต้องอยู่ใน RAM ปรับมาเพื่อเขียนโค้ดแบบเอเจนต์" },
        ["modelsm.desc.kat-coder-v2.5-dev"] = new() { ["en"] = "Agentic-coding specialist (35B MoE, 3B active) built on Qwen3.5. Text only.", ["th"] = "ผู้เชี่ยวชาญเขียนโค้ดแบบเอเจนต์ (MoE 35B ใช้จริง 3B) สร้างบน Qwen3.5 รับเฉพาะข้อความ" },
        ["modelsm.desc.ornith-1.0-9b"] = new() { ["en"] = "A 9B coding agent trained with self-improving RL on top of Qwen3.5 — the best coder that fits an 8 GB card.", ["th"] = "เอเจนต์เขียนโค้ดขนาด 9B ฝึกด้วย RL แบบพัฒนาตัวเองบนพื้นฐาน Qwen3.5 — ตัวเขียนโค้ดที่ดีที่สุดที่ใส่การ์ด 8 GB ได้" },
        ["modelsm.desc.mimo-v2.6-distill-9b"] = new() { ["en"] = "Xiaomi's 9B agent model (Qwen3.5-9B fine-tune): coding, tool use and visual coding from screenshots.", ["th"] = "โมเดลเอเจนต์ 9B ของ Xiaomi (ปรับจาก Qwen3.5-9B) เขียนโค้ด ใช้เครื่องมือ และเขียนโค้ดจากภาพหน้าจอ" },
        ["modelsm.desc.devstral-small-2-24b"] = new() { ["en"] = "Mistral's software-engineering agent model with a 256K context and image input.", ["th"] = "โมเดลเอเจนต์งานวิศวกรรมซอฟต์แวร์ของ Mistral รองรับ context 256K และรับรูปภาพได้" },
        ["modelsm.desc.qwen3-coder-30b-a3b"] = new() { ["en"] = "Proven coding MoE (3.3B active). Fast with CPU offload, solid tool calling.", ["th"] = "MoE สายเขียนโค้ดที่พิสูจน์แล้ว (ใช้จริง 3.3B) เร็วแม้แบ่งไปรันบน CPU เรียกใช้เครื่องมือได้แม่น" },
        ["modelsm.desc.qwen3-coder-next"] = new() { ["en"] = "Workstation-class coder: 80B total, 3B active. Needs about 48 GB of VRAM + RAM combined.", ["th"] = "ตัวเขียนโค้ดระดับเวิร์กสเตชัน รวม 80B ใช้จริง 3B ต้องมี VRAM + RAM รวมกันราว 48 GB" },
        ["modelsm.desc.gemma-4-31b"] = new() { ["en"] = "Google's flagship open model: 140+ languages (excellent Thai), vision, 256K context, strong reasoning.", ["th"] = "โมเดลเปิดรุ่นท็อปของ Google รองรับกว่า 140 ภาษา (ภาษาไทยดีมาก) อ่านรูปได้ context 256K ใช้เหตุผลเก่ง" },
        ["modelsm.desc.gemma-4-26b-a4b"] = new() { ["en"] = "Gemma 4 as a mixture-of-experts: 3.8B active, so it runs fast even partly on the CPU.", ["th"] = "Gemma 4 แบบ MoE ใช้จริง 3.8B จึงรันเร็วแม้บางส่วนอยู่บน CPU" },
        ["modelsm.desc.gemma-4-12b"] = new() { ["en"] = "Mid-size Gemma 4 with built-in image and audio understanding. Great Thai for its size.", ["th"] = "Gemma 4 ขนาดกลาง เข้าใจรูปภาพและเสียงในตัว ภาษาไทยดีเกินขนาด" },
        ["modelsm.desc.gemma-4-e4b"] = new() { ["en"] = "Laptop-class Gemma 4 (4.5B effective) with image and audio input.", ["th"] = "Gemma 4 สำหรับโน้ตบุ๊ก (ประสิทธิผล 4.5B) รับรูปภาพและเสียงได้" },
        ["modelsm.desc.gemma-4-e2b"] = new() { ["en"] = "Smallest Gemma 4 (2.3B effective) — runs on almost anything, even CPU only.", ["th"] = "Gemma 4 ตัวเล็กสุด (ประสิทธิผล 2.3B) รันได้แทบทุกเครื่อง แม้ใช้ CPU อย่างเดียว" },
        ["modelsm.desc.qwen3.5-9b"] = new() { ["en"] = "Best general model for 8 GB cards: multilingual, sees images, 256K context.", ["th"] = "โมเดลทั่วไปที่ดีที่สุดสำหรับการ์ด 8 GB หลายภาษา อ่านรูปได้ context 256K" },
        ["modelsm.desc.qwen3.5-4b"] = new() { ["en"] = "Compact all-rounder for 4–6 GB cards and laptops.", ["th"] = "ตัวเล็กเก่งรอบด้านสำหรับการ์ด 4–6 GB และโน้ตบุ๊ก" },
        ["modelsm.desc.qwen3.5-2b"] = new() { ["en"] = "Tiny and quick — fine for simple chat and short tasks on CPU.", ["th"] = "เล็กและเร็ว เหมาะกับแชตง่ายๆ และงานสั้นๆ บน CPU" },
        ["modelsm.desc.qwen3.5-0.8b"] = new() { ["en"] = "Under 1 GB. For very old hardware or quick experiments.", ["th"] = "ไม่ถึง 1 GB สำหรับเครื่องเก่ามากหรือลองเล่นเร็วๆ" },
        ["modelsm.desc.gpt-oss-20b"] = new() { ["en"] = "OpenAI's open reasoning model (3.6B active). Shipped in MXFP4, so every quant is about the same size.", ["th"] = "โมเดลใช้เหตุผลแบบเปิดของ OpenAI (ใช้จริง 3.6B) เผยแพร่เป็น MXFP4 ทุก quant จึงขนาดใกล้กัน" },
        ["modelsm.desc.nemotron-3.5-lightning-30b-a3b"] = new() { ["en"] = "NVIDIA's hybrid Mamba MoE for agents: 3B active, up to 1M context.", ["th"] = "MoE ไฮบริด Mamba ของ NVIDIA สำหรับงานเอเจนต์ ใช้จริง 3B context สูงสุด 1M" },
        ["modelsm.desc.ministral-3-14b-reasoning"] = new() { ["en"] = "Mistral's 14B thinking model with image input.", ["th"] = "โมเดลคิดก่อนตอบขนาด 14B ของ Mistral รับรูปภาพได้" },
        ["modelsm.desc.nemotron-3-nano-4b"] = new() { ["en"] = "Small hybrid model with a very long (1M) context window.", ["th"] = "โมเดลไฮบริดขนาดเล็ก context ยาวมาก (1M)" },
        ["modelsm.desc.typhoon2.5-qwen3-30b-a3b"] = new() { ["en"] = "Thai-first model from SCB 10X (Qwen3 30B-A3B base): natural Thai, Thai culture and documents, function calling.", ["th"] = "โมเดลภาษาไทยเป็นหลักจาก SCB 10X (ฐาน Qwen3 30B-A3B) ภาษาไทยเป็นธรรมชาติ เข้าใจบริบทไทยและเอกสารไทย เรียกใช้ฟังก์ชันได้" },
        ["modelsm.desc.typhoon2.5-qwen3-4b"] = new() { ["en"] = "Small Thai-first model with a 256K context — Thai chat on modest hardware.", ["th"] = "โมเดลภาษาไทยตัวเล็ก context 256K แชตภาษาไทยได้บนเครื่องสเปกพอประมาณ" },
        ["modelsm.desc.pathumma-thaillm-8b-think"] = new() { ["en"] = "NECTEC's Thai reasoning model on the national ThaiLLM base: step-by-step thinking and tool calling in Thai.", ["th"] = "โมเดลใช้เหตุผลภาษาไทยของ NECTEC บนฐาน ThaiLLM แห่งชาติ คิดเป็นขั้นตอนและเรียกใช้เครื่องมือเป็นภาษาไทย" },
        ["modelsm.desc.qwen2.5-coder-14b"] = new() { ["en"] = "2024 coding model. Superseded by Qwen3.x and Ornith, still runs on the in-process backend.", ["th"] = "โมเดลเขียนโค้ดปี 2024 ถูกแทนที่ด้วย Qwen3.x และ Ornith แล้ว แต่ยังรันบน backend ในตัวได้" },
        ["modelsm.desc.qwen2.5-coder-7b"] = new() { ["en"] = "2024 coding model for 8 GB cards. Superseded by Ornith 1.0 9B.", ["th"] = "โมเดลเขียนโค้ดปี 2024 สำหรับการ์ด 8 GB ถูกแทนที่ด้วย Ornith 1.0 9B แล้ว" },
        ["modelsm.desc.deepseek-r1-distill-14b"] = new() { ["en"] = "Early-2025 distilled reasoning model.", ["th"] = "โมเดลใช้เหตุผลแบบกลั่นจากต้นปี 2025" },
        ["modelsm.desc.gemma-3-12b"] = new() { ["en"] = "Previous-generation Gemma. Gemma 4 12B replaces it.", ["th"] = "Gemma รุ่นก่อน ถูกแทนที่ด้วย Gemma 4 12B แล้ว" },
        ["modelsm.desc.gemma-3-4b"] = new() { ["en"] = "Previous-generation small Gemma.", ["th"] = "Gemma ตัวเล็กรุ่นก่อน" },
        ["modelsm.desc.phi-4-mini"] = new() { ["en"] = "Microsoft's small model from early 2025. English-centred.", ["th"] = "โมเดลเล็กของ Microsoft จากต้นปี 2025 เน้นภาษาอังกฤษ" },
        ["modelsm.desc.llama-3.1-8b"] = new() { ["en"] = "2024 workhorse. Runs on every backend, including the in-process one.", ["th"] = "ตัวหลักปี 2024 รันได้ทุก backend รวมถึง backend ในตัว" },
        ["modelsm.desc.llama-3.2-3b"] = new() { ["en"] = "2024 compact model, fast on CPU.", ["th"] = "โมเดลเล็กปี 2024 เร็วบน CPU" },

